from pathlib import Path
import re
O=Path(__file__).parent;S=O/'src';S.mkdir(exist_ok=True);text=(O/'template.html').read_text(encoding='utf8')
css=re.search(r'<style>(.*?)</style>',text,re.S)[1]
css+='''\n#mobile{display:none}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #286cda;outline-offset:2px}.result:focus-visible{outline:2px solid #286cda}#loading[role=alert]{padding:40px;text-align:center}@media(max-width:850px){#mobile{display:flex;position:fixed;top:10px;left:10px;gap:8px;z-index:4}aside{display:none;left:10px!important;right:10px!important;top:60px!important;bottom:75px!important;height:auto!important;width:auto!important}.show-search #left,.show-detail #right{display:block}.capture #mobile{display:none}#bar{left:10px;right:10px;flex-wrap:wrap;bottom:18px;gap:4px}#bar button{font-size:11px;padding:8px}#status{display:none}#credit{font-size:8px;left:10px;right:10px;bottom:3px}#scale{left:15px;bottom:80px}.capture #bar{left:auto}}
'''
js=re.search(r'<script>(.*?)</script>',text,re.S)[1];js=js.replace("const B64='__DATA_GZIP__';",'const CONFIG=window.ATLAS_CONFIG;')
js=js.replace("let bytes=Uint8Array.from(atob(B64),c=>c.charCodeAt(0));let stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));DATA=JSON.parse(await new Response(stream).text());", "let bytes;if(CONFIG.inlineGzip){bytes=Uint8Array.from(atob(CONFIG.inlineGzip),c=>c.charCodeAt(0))}else{let response=await fetch(CONFIG.dataUrl);if(!response.ok)throw Error('데이터 응답 '+response.status);bytes=new Uint8Array(await response.arrayBuffer())}let decoded;if(bytes[0]===31&&bytes[1]===139){let stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));decoded=await new Response(stream).text()}else{decoded=new TextDecoder().decode(bytes)}DATA=JSON.parse(decoded);if(DATA.meta.schema_version!=='1.0.0')throw Error('지원하지 않는 데이터 스키마');")
js=js.replace("<div class=\"result\" data-i=\"${i}\">", "<div class=\"result\" role=\"button\" tabindex=\"0\" data-i=\"${i}\">")
js=js.replace("function select(i,fly=false){selected=i;", "function select(i,fly=false){selected=i;if(i!==null&&innerWidth<=850){document.body.classList.remove('show-search');document.body.classList.add('show-detail')}")
js=js.replace("el('loading').textContent='지도를 열 수 없습니다.", "el('loading').setAttribute('role','alert');el('loading').textContent='지도를 열 수 없습니다.")
js += '''\nel('toggle-search').onclick=()=>{document.body.classList.remove('show-detail');document.body.classList.toggle('show-search');el('toggle-search').setAttribute('aria-expanded',document.body.classList.contains('show-search'))};el('toggle-detail').onclick=()=>{document.body.classList.remove('show-search');document.body.classList.toggle('show-detail');el('toggle-detail').setAttribute('aria-expanded',document.body.classList.contains('show-detail'))};el('results').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){let a=e.target.closest('[data-i]');if(a){e.preventDefault();select(Number(a.dataset.i),true)}}};\n'''
html=re.sub(r'<style>.*?</style>','__STYLE_TAG__',text,flags=re.S);html=re.sub(r'<script>.*?</script>','__CONFIG_TAG__\n__SCRIPT_TAG__',html,flags=re.S);html=html.replace('<canvas id="map">','<canvas aria-label="수도권 아파트 단지 지도" id="map">');html=html.replace('<aside id="left">','<div id="mobile"><button id="toggle-search" aria-expanded="false" aria-controls="left">검색·지역</button><button id="toggle-detail" aria-expanded="false" aria-controls="right">단지 정보</button></div><aside id="left">');html=html.replace('<div id="loading">','<div id="loading" role="status" aria-live="polite">')
(S/'styles.css').write_text(css,encoding='utf8');(S/'app.js').write_text(js,encoding='utf8');(S/'index.template.html').write_text(html,encoding='utf8')
